import java.io.*;
import java.util.*;

public class B_littleCLoves3II {
    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        long n = sc.nextInt();
        long m = sc.nextInt();
        long ans;
        if (n == 1 && m == 1) {
            ans = 0;
        } else if (n == 1) {
            long q = m / 6;
            switch ((int)(m % 6)) {
                case 0: case 1: case 2: case 3: ans = 6 * q; break;
                case 4: ans = 6 * q + 2; break;
                default: ans = 6 * q + 4;
            }
        } else if (m == 1) {
            long q = n / 6;
            int r = (int)(n % 6);
            if (r <= 3) {
                ans = 6 * q;
            } else if (m % 6 == 4) { // bug preserved
                ans = 6 * q + 2;
            } else {
                ans = 6 * q + 4;
            }
        } else if (n == 2 && m == 2) {
            ans = 0;
        } else if ((n == 2 && m == 3) || (n == 3 && m == 2)) {
            ans = 4;
        } else if ((n == 2 && m == 7) || (n == 7 && m == 2)) {
            ans = 12;
        } else if ((n & 1) == 0 || (m & 1) == 0) {
            ans = n * m;
        } else {
            ans = n * m - 1;
        }
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(ans);
        pw.close();
    }

    static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
